-- Users, organizations and memberships (ADR 0007) with row-level security (ADR 0008).
-- IDs are UUIDv7 generated by the API.

-- +goose Up
-- Fail fast instead of queueing behind other locks (foreign keys lock the referenced table).
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TABLE users (
    id            uuid        PRIMARY KEY,
    email         text        NOT NULL,
    full_name     text        NOT NULL,
    phone         text,
    password_hash text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_email_key UNIQUE (email),
    CONSTRAINT users_email_lowercase CHECK (email = lower(email)),
    CONSTRAINT users_email_length CHECK (char_length(email) BETWEEN 3 AND 255),
    CONSTRAINT users_full_name_length CHECK (char_length(full_name) BETWEEN 1 AND 150),
    CONSTRAINT users_phone_length CHECK (phone IS NULL OR char_length(phone) BETWEEN 6 AND 30)
);

CREATE TABLE organizations (
    id         uuid        PRIMARY KEY,
    name       text        NOT NULL,
    slug       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT organizations_slug_key UNIQUE (slug),
    CONSTRAINT organizations_slug_format CHECK (slug ~ '^[a-z0-9-]{3,40}$'),
    CONSTRAINT organizations_name_length CHECK (char_length(name) BETWEEN 1 AND 100)
);

CREATE TABLE memberships (
    organization_id uuid        NOT NULL REFERENCES organizations (id),
    user_id         uuid        NOT NULL REFERENCES users (id),
    role            text        NOT NULL,
    status          text        NOT NULL DEFAULT 'active',
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (organization_id, user_id),
    CONSTRAINT memberships_role_valid CHECK (role IN ('owner', 'admin', 'member')),
    CONSTRAINT memberships_status_valid CHECK (status IN ('active', 'deactivated'))
);

-- "My organizations" looks memberships up by user.
-- The table is created empty in this same migration, so a plain index blocks nobody.
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX memberships_user_id_idx ON memberships (user_id);

-- The request scope, set per transaction by the API's unit of work (SET LOCAL).
-- An unset scope is NULL, which matches no row.
CREATE FUNCTION app_user_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$ SELECT NULLIF(current_setting('app.user_id', true), '')::uuid $$;

CREATE FUNCTION app_org_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$ SELECT NULLIF(current_setting('app.org_id', true), '')::uuid $$;

-- FORCE applies the policies to the table owner too: nobody reads tenant data without a scope.
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;

-- A member sees an organization they belong to; writes need that organization as the scope.
CREATE POLICY organizations_tenant ON organizations
    USING (
        id = app_org_id()
        OR EXISTS (SELECT 1 FROM memberships m WHERE m.organization_id = organizations.id AND m.user_id = app_user_id())
    )
    WITH CHECK (id = app_org_id());

-- Rows of the scoped organization, plus the signed-in user's own memberships (to list "my organizations").
CREATE POLICY memberships_tenant ON memberships
    USING (organization_id = app_org_id() OR user_id = app_user_id())
    WITH CHECK (organization_id = app_org_id());

-- +goose Down
-- Down undoes the Up above on a database that has not been used yet; dropping is its purpose.
-- The organizations policy reads memberships, so it goes first.
DROP POLICY organizations_tenant ON organizations;
-- squawk-ignore ban-drop-table
DROP TABLE memberships;
-- squawk-ignore ban-drop-table
DROP TABLE organizations;
-- squawk-ignore ban-drop-table
DROP TABLE users;
-- squawk-ignore ban-drop-function
DROP FUNCTION app_org_id();
-- squawk-ignore ban-drop-function
DROP FUNCTION app_user_id();
